from itertools import combinations, product

def sat_exists(clauses, n, fixed):
    # fixed: dict var->val; check if some assignment (others free) satisfies all clauses exactly-one
    free = [v for v in range(n) if v not in fixed]
    for vals in product([0,1], repeat=len(free)):
        a = dict(fixed); a.update(dict(zip(free, vals)))
        if all(sum(a[v] for v in cl)==1 for cl in clauses):
            return True
    return False

def search_constant(k, maxc, target):
    # var 0 is the constant we want forced to target; aux 1..k
    n = k+1
    pool = list(combinations(range(n),3))
    def ok(clauses):
        # satisfiable with var0=target and all assignments with var0=1-target unsatisfiable
        if not sat_exists(clauses, n, {0:target}): return False
        if sat_exists(clauses, n, {0:1-target}): return False
        return True
    for r in range(1, maxc+1):
        for sub in combinations(pool, r):
            if ok(sub): return sub
    return None

for k in range(1,6):
    for mc in range(1,7):
        r = search_constant(k, mc, 0)
        if r: print("FALSE const k",k,"mc",mc,r); break
    else:
        continue
    break
else:
    print("no false const")

for k in range(1,6):
    for mc in range(1,7):
        r = search_constant(k, mc, 1)
        if r: print("TRUE const k",k,"mc",mc,r); break
    else:
        continue
    break
else:
    print("no true const")
