from itertools import combinations, product

def find_or_with_false(k, max_clauses):
    # vars: 0,1,2 = l1,l2,l3 ; 3 = F (fixed 0) ; 4..4+k-1 aux
    n = 4+k
    aux = list(range(4,n))
    NA = 1<<k
    auxvals = [tuple((a>>i)&1 for i in range(k)) for a in range(NA)]
    pool = list(combinations(range(n),3))
    def cmask(clause, lvals):
        m=0
        for a in range(NA):
            av=auxvals[a]; val=0
            for v in clause:
                if v<3: val+=lvals[v]
                elif v==3: val+=0
                else: val+=av[v-4]
            if val==1: m|=(1<<a)
        return m
    cm = [[cmask(c, tuple((l>>i)&1 for i in range(3))) for l in range(8)] for c in pool]
    full=(1<<NA)-1
    # OR=0 is l=000 -> index 0 ; OR=1 others
    def dfs(start, cur, used):
        if all(cur[l]==0 for l in range(1,8)):
            return False  # invalid, some OR=1 l impossible
        if cur[0]==0:
            if all(cur[l]!=0 for l in range(1,8)):
                return list(used)
            return None
        if len(used)>=max_clauses: return None
        for i in range(start,len(pool)):
            new=[cur[l]&cm[i][l] for l in range(8)]
            if any(new[l]==0 for l in range(1,8)): continue
            used.append(pool[i])
            r=dfs(i+1,new,used)
            if r: return r
            used.pop()
        return None
    return dfs(0,[full]*8,[])

for k in range(1,6):
    for mc in range(1,8):
        r=find_or_with_false(k,mc)
        if r:
            print("FOUND k",k,"mc",mc,r); raise SystemExit
        print("k",k,"mc",mc,"none")
print("none")
EOF
